try {
  const res = await fetch('https://www.mongodb.com/docs/vector-search/tutorials/quick-start/?deployment-type=atlas&interface=atlas-ui&embedding=auto');
  const text = await res.text();
  nodeRepl.write(JSON.stringify({ok:true, status: res.status, length: text.length, last50: text.slice(-50)}));
} catch (e) {
  nodeRepl.write(JSON.stringify({ok:false, error: String(e)}));
}
